import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const UploadPage = () => {
  const navigate = useNavigate();
  const [calendarUploaded, setCalendarUploaded] = useState(false);
  const [files, setFiles] = useState({
    calendar: null,
    baseline: null,
    bfd: null,
    upside: null,
    mostlikely: null,
  });

  const handleFileChange = (type, file) => {
    if (type !== 'calendar' && !calendarUploaded) {
      alert('Please upload Calendar Holiday sheet first.');
      return;
    }

    setFiles((prev) => ({ ...prev, [type]: file }));
    if (type === 'calendar') setCalendarUploaded(true);
  };

  const handleSubmit = () => {
    console.log('Uploaded files:', files);
    alert('Files uploaded successfully!');
    navigate('/');
  };

  return (
    <div className="upload-page">
      <h2>Upload Revenue Forecast Sheets</h2>
      <div className="upload-cards">
        {[
          { key: 'calendar', label: 'Calendar Holiday' },
          { key: 'baseline', label: 'Baseline' },
          { key: 'bfd', label: 'BFD' },
          { key: 'upside', label: 'Upside' },
          { key: 'mostlikely', label: 'Most Likely' },
        ].map(({ key, label }) => (
          <div key={key} className="upload-card">
            <h3>{label}</h3>
            <input
              type="file"
              accept=".xlsx, .xls"
              onChange={(e) => handleFileChange(key, e.target.files[0])}
            />
          </div>
        ))}
      </div>
      <div className="upload-actions">
        <button onClick={() => navigate('/')}>Back</button>
        <button onClick={handleSubmit}>Submit</button>
      </div>
    </div>
  );
};

export default UploadPage;
